import java.sql.*;
import java.util.*;

public class Main {
    private static final String URL = "jdbc:h2:mem:toko;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1";

    static void siapkan(Connection c) throws SQLException {
        try (Statement st = c.createStatement()) {
            st.execute("CREATE TABLE pengguna (nama VARCHAR(50) PRIMARY KEY, sandi VARCHAR(50) NOT NULL)");
            st.executeUpdate("INSERT INTO pengguna VALUES ('sari', 'kopi123'), ('budi', 'teh456')");
        }
    }

    public static void main(String[] args) throws SQLException {
        Scanner in = new Scanner(System.in);
        try (Connection c = DriverManager.getConnection(URL, "sa", "")) {
            siapkan(c);
            while (in.hasNextLine()) {
                String[] d = in.nextLine().split(" ", 2);
                try (PreparedStatement ps = c.prepareStatement("SELECT COUNT(*) FROM pengguna WHERE nama = ? AND sandi = ?")) {
                    ps.setString(1, d[0]);
                    ps.setString(2, d[1]);
                    try (ResultSet rs = ps.executeQuery()) {
                        rs.next();
                        System.out.println(d[0] + ": " + (rs.getInt(1) > 0 ? "berhasil masuk" : "ditolak"));
                    }
                }
            }
        }
    }
}
